"""Render the explanatory publication; C++ remains the research implementation.
Authoring dependency: Python markdown. No Python is needed by the served page.
"""
from pathlib import Path
import html
import markdown
root=Path(__file__).resolve().parent.parent
parent=(root/'index.html').read_text()
style=parent.split('<style>',1)[1].split('</style>',1)[0]
lesson=(root/'lessons/03-unbounded-progression-words.md').read_text()
body=markdown.markdown(lesson,extensions=['fenced_code','tables'])
body=body.replace('href="02-legal-progression-logic.md"','href="../progression-logic/"')
body=body.replace('<table>','<div class="table-wrap"><table>').replace('</table>','</table></div>')
output=html.escape((root/'data/progression-words/demo.txt').read_text())
widget='''<section id="try-counts" aria-labelledby="count-heading"><p class="eyebrow">A worked picture</p><h2 id="count-heading">Append two histories, or repeat a whole block?</h2><p>One <b>c</b> is the four-ply knight dance. Every chip below stands for one whole dance. All counts refer to the declared movement-only variant.</p><div class="dance"><span>White: g1 → f3</span><span>Black: g8 → f6</span><span>White: f3 → g1</span><span>Black: f6 → g8</span></div><div class="count-controls"><label>First word: <output id="a-value">3</output> cycles<input id="a" type="range" min="0" max="8" value="3"></label><label>Second word: <output id="b-value">4</output> cycles<input id="b" type="range" min="0" max="8" value="4"></label></div><div class="comparison"><article><h3>Concatenation</h3><p>Append the second word to the first.</p><p id="sum" class="equation" aria-live="polite">c^3 ; c^4 = c^7 · 28 plies</p><div id="sum-chips" class="chips" aria-hidden="true"></div></article><article><h3>Added Repeat operation</h3><p>Copy the first word as many times as the second word counts.</p><p id="product" class="equation" aria-live="polite">Repeat(c^3, c^4) = c^12 · 48 plies</p><div id="product-chips" class="chips" aria-hidden="true"></div></article></div><p class="note">With zero cycles, the word is empty (ε). Moving a slider illustrates the definitions; the recorded C++ results and tests appear below.</p></section>'''
extra='''.dance,.count-controls{display:flex;flex-wrap:wrap;gap:14px}.dance span{background:#e5eff0;padding:9px;font:14px/1.5 system-ui}.count-controls{margin:25px 0}.count-controls label{flex:1;min-width:200px;font:16px/1.5 system-ui}input[type=range]{display:block;width:100%;accent-color:#326e88;margin:12px 0}.comparison{display:grid;grid-template-columns:1fr 1fr;gap:20px}.comparison article{padding:20px;background:#edf3f2;border-radius:8px}.comparison h3{margin-top:0}.equation{font:16px/1.6 ui-monospace,monospace;overflow-wrap:anywhere}.chips{display:flex;flex-wrap:wrap;gap:6px}.chip{display:inline-block;background:#1c657b;color:white;padding:1px 8px;border-radius:4px;font:14px/1.7 ui-monospace,monospace}.chip.second{background:#705295}.block{display:inline-flex;flex-wrap:wrap;gap:3px;border:1px solid #8fa9b1;padding:4px;border-radius:5px;max-width:100%}h1{font-size:clamp(36px,6vw,66px)}h2{margin-top:50px}main{max-width:980px}li{margin:10px 0}.table-wrap{margin:25px 0}#try-counts{padding-bottom:30px;border-bottom:1px solid #c7d9dd}@media(max-width:650px){.comparison{grid-template-columns:1fr}.count-controls label{min-width:100%}}'''
script='''const a=document.querySelector('#a'),b=document.querySelector('#b');
function chip(second=false){const e=document.createElement('span');e.className='chip'+(second?' second':'');e.textContent='c';return e;}
function update(){const x=Number(a.value),y=Number(b.value);document.querySelector('#a-value').textContent=x;document.querySelector('#b-value').textContent=y;document.querySelector('#sum').textContent=`c^${x} ; c^${y} = c^${x+y} · ${4*(x+y)} plies`;document.querySelector('#product').textContent=`Repeat(c^${x}, c^${y}) = c^${x*y} · ${4*x*y} plies`;const sum=document.querySelector('#sum-chips'),product=document.querySelector('#product-chips');sum.replaceChildren();product.replaceChildren();for(let i=0;i<x+y;i++)sum.append(chip(i>=x));if(x+y===0)sum.textContent='ε';for(let j=0;j<y&&x>0;j++){const block=document.createElement('span');block.className='block';for(let i=0;i<x;i++)block.append(chip(j%2===1));product.append(block);}if(x*y===0)product.textContent='ε';}
a.addEventListener('input',update);b.addEventListener('input',update);update();'''
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Progression words: addition & repetition | Michael Emanuel Glover</title><meta name="description" content="Understand a C++ chess-progression word model: a knight-loop example, exact addition, the multiplication boundary and an explicit Repeat extension."><style>'''+style+extra+'''</style><main><nav><a href="../">← Magnum Chessicus C++</a><a href="../progression-logic/">Previous lesson</a><a href="../lessons/03-unbounded-progression-words.md">Markdown</a><a href="../MAGNUM_CPP_SOURCE.zip">Source ZIP</a><a href="#try-counts">Try the counts</a></nav><p class="eyebrow">Michael Emanuel Glover · C++ research lesson · 14 November 2026</p>'''
# Put the worked illustration after the reader guide and before the formal sections.
needle='<h2>1. Remove a bound explicitly</h2>'
assert needle in body
body=body.replace(needle,widget+needle,1)
page+=body+'''<section><h2>Recorded executable example</h2><pre>'''+output+'''</pre><p><a href="../data/progression-words/demo.txt">Plain-text output</a> · <a href="../tests/word_tests.cpp">Executable checks</a></p></section><footer>Originating proposal and research direction: Michael Emanuel Glover. Formalization, implementation and checks with Cypher.</footer></main><script>'''+script+'''</script></html>'''
(root/'progression-words/index.html').write_text(page)
print('Rendered explanatory lesson and interactive worked example.')
